{"id":"35700d87-e06b-46ba-8fd5-cbac3b19c882","type":"https://serlo.org/editor","variant":"serlo-org","domainOrigin":"serlo.org","version":2,"editorVersion":"0.22.0","dateModified":"2025-02-26T18:25:46.412Z","document":{"plugin":"exercise","state":{"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Ein Zylinder hat eine Oberfläche von "},{"type":"math","src":"O_{\mathrm{Zylinder}} = 50 \,\mathrm{cm^2}","inline":true,"children":[{"text":""}]},{"text":". Der Radius beträgt "},{"type":"math","src":"r = 2 \,\mathrm{cm}","inline":true,"children":[{"text":""}]},{"text":". Berechne die Höhe "},{"type":"math","src":"h","inline":true,"children":[{"text":""}]},{"text":" des Zylinders. Runde das Ergebnis auf ganze Zahlen."}]}],"id":"8b34f77d-d9cc-4293-aa08-3dded4525c1f"}],"id":"83293f37-45d7-4ddf-a1ad-97ad19e12ff1"},"interactive":{"plugin":"inputExercise","state":{"type":"input-expression-equal-match-challenge","unit":"cm","answers":[{"value":"2","isCorrect":true,"feedback":{"plugin":"text","state":[{"type":"p","children":[{"text":"Gut gemacht!"}]}],"id":"66ad2710-6c18-435e-a679-b51fd2719529"}}]},"id":"37c9223e-e4d4-4cbe-9a6f-cbb43ba99c2b"},"solution":{"plugin":"solution","state":{"prerequisite":{"id":"1555","title":"Zylinder"},"strategy":{"plugin":"text","state":[{"type":"p","children":[{"text":""}]}],"id":"e16e5627-6144-4c50-ad91-98d2912029a5"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Die allgemeine Formel zur Berechnung der Oberfläche des Zylinders ist:"}]}],"id":"f67a650d-1e3a-4f50-a82b-c935dff7bda6"},{"plugin":"text","state":[{"type":"math","src":"\begin{array}{rcl} 
O_{\mathrm{Zylinder}} &=& 2 \cdot A_{\mathrm{Kreis}} &+& A_{\mathrm{Mantel}} \\
O_{\mathrm{Zylinder}} &=& 2\pi r^2 &+& 2\pi rh \\

  \end{array}","inline":false,"children":[{"text":""}]}],"id":"4cf569fb-c6c8-4a3d-90d1-035064fcf0a3"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Diese Formel musst du nach "},{"type":"math","src":"h","inline":true,"children":[{"text":""}]},{"text":" umstellen."}]}],"id":"13b1d2cc-d8bc-4160-80b9-b0b0e724cf3c"},{"plugin":"text","state":[{"type":"math","src":"\begin{array}{rcl} 
O_{\mathrm{Zylinder}} &=& 2\pi r^2 &+& 2\pi rh \\\\
O_{\mathrm{Zylinder}} - 2 \pi r^2 &=& 2 \pi rh \\\\
\dfrac{O_{\mathrm{Zylinder}} - 2\pi r^2}{2\pi r} &=& h \\\\
\dfrac{50 \,\mathrm{cm^2} - 2\pi (2 \,\mathrm{cm})^2}{2\pi \cdot  2\,\mathrm{cm}} &=& h \\\\
\dfrac{50 \,\mathrm{cm^2} - \pi \cdot 8 \,\mathrm{cm}^2}{\pi \cdot 4\,\mathrm{cm}} &=& h \\\\
h &\approx& 2 \,\mathrm{cm}
  \end{array}","inline":false,"children":[{"text":""}]}],"id":"df82d47d-8d76-429d-9494-a9daf21baf82"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Daraus folgt, dass der Zylinder eine Höhe von ca. 2 cm hat."}]}],"id":"6750a2a6-7474-45bd-af0e-795ea0189983"}],"id":"ac024bdf-89ce-4440-a98a-503f883bfc4e"}},"id":"f1f2dda3-3bf2-4c7e-b972-e8b2bcad4b9e"}},"id":"d21ee410-e005-473d-8eac-50dd3509960e"}}
